  max-width: 80% !important;
}
.chat-message-markdown p { margin: 0 0 0.4rem 0; }
.chat-message-markdown p:last-child { margin-bottom: 0; }
.chat-message-markdown ol, .chat-message-markdown ul { padding-left: 1.15rem; margin: 0.25rem 0; }
.chat-message-markdown li { margin-bottom: 0.5rem; padding-left: 0.15rem; }
.chat-message-markdown strong { font-weight: 600; }
.chat-message-markdown code { white-space: pre-wrap; word-break: break-word; background: #f4f6f8; padding: 0.05rem 0.25rem; border-radius: 4px; }

